<script setup>
import { onMounted } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import FamilyLayout from '@/Layouts/FamilyLayout.vue';
import {useFamilyCopy} from '@/lib/family';
const props=defineProps({activate:Boolean});const {l}=useFamilyCopy();
const form=useForm({nursery_code:'',email:'',password:'',password_confirmation:'',token:''});
onMounted(()=>{if(props.activate){form.token=new URLSearchParams(location.hash.slice(1)).get('token')||'';history.replaceState(null,'',location.pathname);}});
function submit(){form.post(props.activate?'/family/activate':'/family/login',{onFinish:()=>{form.reset('password','password_confirmation');}});}
</script>
<template><Head :title="l('مساحة الأسرة','Family space')"><meta name="robots" content="noindex,nofollow"/></Head><FamilyLayout :signed-in="false"><section class="family-card family-auth"><p class="eyebrow">{{l('البيت والحضانة، أقرب','Home and nursery, closer')}}</p><h1>{{activate?l('ابدأ مساحة أسرتك','Start your family space'):l('أهلاً بالأسرة','Welcome, family')}}</h1><p class="family-muted">{{activate?l('الدعوة تربط هذا الحساب بالطفل الذي اعتمدته الحضانة فقط. لو عندك حساب، استخدم كلمة مروره الحالية.','Your invitation grants access only to the child approved by the nursery. If you have an account, use its current password.'):l('استخدم رمز الحضانة والبريد وكلمة المرور. تحتاج دعوة معتمدة من الحضانة لأول دخول.','Use your nursery code, email and password. Your first visit needs a nursery-approved invitation.')}}</p><form @submit.prevent="submit" class="family-form"><label v-if="!activate">{{l('رمز الحضانة','Nursery code')}}<input v-model="form.nursery_code" dir="ltr" autocomplete="organization" required/></label><label>{{l('البريد الإلكتروني','Email')}}<input v-model="form.email" type="email" dir="ltr" autocomplete="username" required/></label><label>{{l('كلمة المرور','Password')}}<input v-model="form.password" type="password" :autocomplete="activate?'new-password':'current-password'" :minlength="activate?12:undefined" required/></label><label v-if="activate">{{l('تأكيد كلمة المرور','Confirm password')}}<input v-model="form.password_confirmation" type="password" autocomplete="new-password" minlength="12" required/></label><p v-if="activate" class="family-muted">{{l('للحساب الجديد: ١٢ حرفاً على الأقل. الدعوة لا تغيّر كلمة مرور حساب قائم.','New accounts: at least 12 characters. Invitations do not reset an existing account password.')}}</p><p v-for="(error,key) in form.errors" :key="key" class="family-error" role="alert">{{error}}</p><button class="family-primary" :disabled="form.processing">{{activate?l('تفعيل المساحة','Activate family space'):l('تسجيل الدخول','Sign in')}}</button></form><Link v-if="activate" href="/family/login" class="family-text-link">{{l('عندي حساب بالفعل','I already have an account')}}</Link></section></FamilyLayout></template>
